INSERT INTO public.quiz_questions (topic_id, question_type, question_text, options, correct_answer, explanation, difficulty, xp_reward, time_limit_seconds)
VALUES 
-- Motion & Forces questions (topic: 02b0b331-c14c-4df2-be13-2d8b24897e28)
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'What is the SI unit of force?', '["Joule", "Newton", "Watt", "Pascal"]', 'Newton', 'The SI unit of force is the Newton (N), named after Sir Isaac Newton.', 1, 10, 30),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'A car accelerates from 0 to 20 m/s in 5 seconds. What is its acceleration?', '["2 m/s²", "4 m/s²", "5 m/s²", "100 m/s²"]', '4 m/s²', 'Acceleration = change in velocity / time = 20/5 = 4 m/s²', 2, 15, 45),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'According to Newton''s First Law, an object at rest will:', '["Always accelerate", "Remain at rest unless acted upon by a force", "Move in a circle", "Lose energy"]', 'Remain at rest unless acted upon by a force', 'Newton''s First Law states that objects maintain their state of motion unless acted upon by an unbalanced force.', 1, 10, 30),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'What force keeps a satellite in orbit around Earth?', '["Friction", "Tension", "Gravitational force", "Magnetic force"]', 'Gravitational force', 'Gravitational force provides the centripetal force needed to keep satellites in circular orbit.', 2, 15, 45),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'The acceleration due to gravity on Earth is approximately:', '["5 m/s²", "10 m/s²", "15 m/s²", "20 m/s²"]', '10 m/s²', 'The acceleration due to gravity on Earth is approximately 9.8 m/s² ≈ 10 m/s².', 1, 10, 30),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'A 5 kg object experiences a net force of 20 N. What is its acceleration?', '["2 m/s²", "4 m/s²", "25 m/s²", "100 m/s²"]', '4 m/s²', 'Using F = ma, acceleration = F/m = 20/5 = 4 m/s²', 2, 15, 45),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'Distance is a _____ quantity while displacement is a _____ quantity.', '["vector, scalar", "scalar, vector", "scalar, scalar", "vector, vector"]', 'scalar, vector', 'Distance has only magnitude (scalar), displacement has magnitude and direction (vector).', 1, 10, 30),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'The gradient of a distance-time graph represents:', '["Acceleration", "Speed", "Force", "Energy"]', 'Speed', 'The gradient (slope) of a distance-time graph gives the speed of the object.', 2, 15, 45),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'What is the weight of a 10 kg mass on Earth (g = 10 m/s²)?', '["10 N", "100 N", "1000 N", "1 N"]', '100 N', 'Weight = mass × g = 10 × 10 = 100 N', 1, 10, 30),
('02b0b331-c14c-4df2-be13-2d8b24897e28', 'mcq', 'Hooke''s Law states that extension is proportional to:', '["Mass", "Force applied", "Temperature", "Volume"]', 'Force applied', 'Hooke''s Law: F = kx, where extension x is proportional to force F.', 2, 15, 45),

-- Energy questions (topic: afbc81c9-5f11-4254-a9a5-64ed0b82071e)
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'What is the SI unit of energy?', '["Newton", "Joule", "Watt", "Volt"]', 'Joule', 'The SI unit of energy is the Joule (J).', 1, 10, 30),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'Kinetic energy depends on:', '["Mass only", "Velocity only", "Both mass and velocity", "Neither"]', 'Both mass and velocity', 'KE = ½mv², so kinetic energy depends on both mass and velocity.', 2, 15, 45),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'Power is defined as:', '["Force × distance", "Energy / time", "Mass × acceleration", "Voltage × current"]', 'Energy / time', 'Power = Work done / Time = Energy transferred / Time', 1, 10, 30),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'A 2 kg object is lifted 5 m high. What is its gravitational PE? (g = 10 m/s²)', '["10 J", "25 J", "50 J", "100 J"]', '100 J', 'GPE = mgh = 2 × 10 × 5 = 100 J', 2, 15, 45),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'The SI unit of power is:', '["Joule", "Newton", "Watt", "Ampere"]', 'Watt', 'The SI unit of power is the Watt (W), where 1 W = 1 J/s.', 1, 10, 30),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'What is the kinetic energy of a 4 kg object moving at 3 m/s?', '["6 J", "12 J", "18 J", "36 J"]', '18 J', 'KE = ½mv² = ½ × 4 × 3² = ½ × 4 × 9 = 18 J', 2, 15, 45),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'Efficiency is calculated as:', '["Input / Output × 100%", "Output / Input × 100%", "Output - Input", "Input + Output"]', 'Output / Input × 100%', 'Efficiency = (Useful output energy / Total input energy) × 100%', 2, 15, 45),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'Work done is calculated by:', '["Force × time", "Force × distance", "Mass × velocity", "Energy × time"]', 'Force × distance', 'Work = Force × Distance moved in direction of force', 1, 10, 30),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'Which energy transformation occurs in a hydroelectric dam?', '["Chemical to electrical", "Nuclear to thermal", "Gravitational PE to electrical", "Solar to chemical"]', 'Gravitational PE to electrical', 'Water falls (GPE converts to KE), then turbines convert KE to electrical energy.', 2, 15, 45),
('afbc81c9-5f11-4254-a9a5-64ed0b82071e', 'mcq', 'If a machine has 80% efficiency and input is 100 J, what is the useful output?', '["20 J", "80 J", "100 J", "180 J"]', '80 J', 'Useful output = Efficiency × Input = 0.80 × 100 = 80 J', 2, 15, 45),

-- Waves questions (topic: 42b67bf6-b73a-4602-bb2c-cb29a50e1a25)
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'Sound waves are examples of:', '["Transverse waves", "Longitudinal waves", "Electromagnetic waves", "Surface waves"]', 'Longitudinal waves', 'Sound waves are longitudinal waves where particles vibrate parallel to wave direction.', 1, 10, 30),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'The wave equation is:', '["v = f/λ", "v = fλ", "v = λ/f", "f = vλ"]', 'v = fλ', 'Wave speed = frequency × wavelength (v = fλ)', 2, 15, 45),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'Light travels fastest in:', '["Water", "Glass", "Vacuum", "Air"]', 'Vacuum', 'Light travels at maximum speed (3 × 10⁸ m/s) in a vacuum.', 1, 10, 30),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'When light passes from air to glass, it:', '["Speeds up and bends away from normal", "Slows down and bends toward normal", "Speeds up and bends toward normal", "Does not bend"]', 'Slows down and bends toward normal', 'Light slows in denser medium and bends toward the normal.', 2, 15, 45),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'The frequency of a wave is measured in:', '["Metres", "Seconds", "Hertz", "Joules"]', 'Hertz', 'Frequency is measured in Hertz (Hz), which is cycles per second.', 1, 10, 30),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'A wave has frequency 50 Hz and wavelength 2 m. What is its speed?', '["25 m/s", "52 m/s", "100 m/s", "0.04 m/s"]', '100 m/s', 'v = fλ = 50 × 2 = 100 m/s', 2, 15, 45),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'The amplitude of a wave represents:', '["Speed", "Maximum displacement", "Frequency", "Wavelength"]', 'Maximum displacement', 'Amplitude is the maximum displacement from the equilibrium position.', 1, 10, 30),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'Total internal reflection occurs when:', '["Light enters a denser medium", "Light hits a mirror", "Angle of incidence exceeds critical angle", "Light is absorbed"]', 'Angle of incidence exceeds critical angle', 'Total internal reflection occurs when light in denser medium exceeds critical angle.', 3, 20, 60),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'Which wave type can travel through a vacuum?', '["Sound", "Water waves", "Electromagnetic waves", "Seismic P-waves"]', 'Electromagnetic waves', 'EM waves (like light) can travel through vacuum; sound needs a medium.', 1, 10, 30),
('42b67bf6-b73a-4602-bb2c-cb29a50e1a25', 'mcq', 'Diffraction is most noticeable when:', '["Gap is much larger than wavelength", "Gap is similar size to wavelength", "Wave speed is high", "Frequency is low"]', 'Gap is similar size to wavelength', 'Diffraction is most pronounced when gap size ≈ wavelength.', 2, 15, 45),

-- Electricity questions (topic: c341db5b-135a-43ef-8b66-54287ab816ca)
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'Electric current is measured in:', '["Volts", "Ohms", "Amperes", "Watts"]', 'Amperes', 'Electric current is measured in Amperes (A).', 1, 10, 30),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'Ohm''s Law states that:', '["V = IR", "P = IV", "E = mc²", "F = ma"]', 'V = IR', 'Ohm''s Law: Voltage = Current × Resistance (V = IR)', 1, 10, 30),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'What is the resistance of a circuit with 12V and 3A current?', '["4 Ω", "9 Ω", "15 Ω", "36 Ω"]', '4 Ω', 'R = V/I = 12/3 = 4 Ω', 2, 15, 45),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'In a series circuit, the current is:', '["Different at each component", "Same throughout", "Zero", "Infinite"]', 'Same throughout', 'In series circuits, current is the same through all components.', 1, 10, 30),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'Two 10Ω resistors in parallel have total resistance of:', '["20 Ω", "10 Ω", "5 Ω", "0.2 Ω"]', '5 Ω', 'For equal parallel resistors: R_total = R/n = 10/2 = 5 Ω', 2, 15, 45),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'Electrical power is calculated by:', '["P = V/I", "P = IR", "P = IV", "P = I/V"]', 'P = IV', 'Electrical power P = Current × Voltage = IV', 2, 15, 45),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'A 60W light bulb running for 2 hours uses how much energy?', '["30 Wh", "60 Wh", "120 Wh", "3600 Wh"]', '120 Wh', 'Energy = Power × Time = 60W × 2h = 120 Wh', 2, 15, 45),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'The unit of electrical resistance is:', '["Ampere", "Volt", "Ohm", "Watt"]', 'Ohm', 'Electrical resistance is measured in Ohms (Ω).', 1, 10, 30),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'In a parallel circuit, voltage across each branch is:', '["Different", "Same", "Zero", "Doubled"]', 'Same', 'In parallel circuits, voltage is the same across all branches.', 1, 10, 30),
('c341db5b-135a-43ef-8b66-54287ab816ca', 'mcq', 'What happens to resistance when a wire is heated?', '["Decreases", "Increases", "Stays the same", "Becomes zero"]', 'Increases', 'For metals, resistance increases with temperature due to more atomic vibrations.', 2, 15, 45);